    }

    print("Test  7: f(x,y) = x / y grad...... ")
    if test_div_grad() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("Test  8: (x+1)*(x-1) diff of sq... ")
