//@ run-pass
// Advanced Sobol sensitivity analysis tests
// Validates Saltelli et al. (2008) methods for second-order indices
// and efficient N(2d+2) sampling scheme.
//
// References:
//   Saltelli, A. et al. (2008) "Global Sensitivity Analysis: The Primer"
//   Ishigami, T. & Homma, T. (1990) "An importance quantification technique
//     in uncertainty analysis for computer models"

extern "C" {
    fn sqrt(x: f64) -> f64;
    fn sin(x: f64) -> f64;
    fn cos(x: f64) -> f64;
    fn log(x: f64) -> f64;
    fn exp(x: f64) -> f64;
}

fn sqrt_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 }
    return sqrt(x)
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn max_f64(a: f64, b: f64) -> f64 {
    if a > b { a } else { b }
}

fn min_f64(a: f64, b: f64) -> f64 {
    if a < b { a } else { b }
}

// ============================================================================
// Van der Corput helper (duplicated here for standalone test compilation)
// ============================================================================

fn reverse_bits(n: i64) -> f64 {
    var result: f64 = 0.0
    var v = n
    var b: f64 = 0.5
    while v > 0 {
        if (v % 2) == 1 {
            result = result + b
        }
        v = v / 2
        b = b / 2.0
    }
    return result
}

// ============================================================================
// Saltelli infrastructure (inline for standalone test)
// ============================================================================

struct SaltelliSamples {
    matrix_a: [f64; 5000],
    matrix_b: [f64; 5000],
    n_samples: i32,
    n_dims: i32,
}

fn saltelli_dim_prime(d: i32) -> i64 {
    if d == 0 { return 2 }
    if d == 1 { return 3 }
    if d == 2 { return 5 }
    if d == 3 { return 7 }
    if d == 4 { return 11 }
    if d == 5 { return 13 }
    if d == 6 { return 17 }
    if d == 7 { return 19 }
    if d == 8 { return 23 }
    return 29
}

fn saltelli_generate(n_samples: i32, n_dims: i32, seed: i64) -> SaltelliSamples {
    var result = SaltelliSamples {
        matrix_a: [0.0; 5000],
        matrix_b: [0.0; 5000],
        n_samples: n_samples,
        n_dims: n_dims,
    }

    var actual_samples = n_samples
    if n_dims > 0 {
        let max_rows = 5000 / n_dims
        if actual_samples > max_rows {
            actual_samples = max_rows
        }
    }
    result.n_samples = actual_samples

    var i: i32 = 0
    while i < actual_samples {
        let base_idx: i64 = (i as i64) + 1 + seed
        var d: i32 = 0
        while d < n_dims {
            let dim_mult = saltelli_dim_prime(d)
            let idx_a: i64 = base_idx * dim_mult + (d as i64)
            let idx_b: i64 = base_idx * dim_mult + (d as i64) + (actual_samples as i64) * 7 + 131

            let flat = i * n_dims + d
            result.matrix_a[flat] = reverse_bits(idx_a)
            result.matrix_b[flat] = reverse_bits(idx_b)

            d = d + 1
        }
        i = i + 1
    }

    return result
}

fn saltelli_build_ci(samples: &SaltelliSamples, dim_i: i32) -> [f64; 5000] {
    var ci: [f64; 5000] = [0.0; 5000]
    var i: i32 = 0
    while i < samples.n_samples {
        var d: i32 = 0
        while d < samples.n_dims {
            let flat = i * samples.n_dims + d
            if d == dim_i {
                ci[flat] = samples.matrix_b[flat]
            } else {
                ci[flat] = samples.matrix_a[flat]
            }
            d = d + 1
        }
        i = i + 1
    }
    return ci
}

fn saltelli_build_cij(samples: &SaltelliSamples, dim_i: i32, dim_j: i32) -> [f64; 5000] {
    var cij: [f64; 5000] = [0.0; 5000]
    var r: i32 = 0
    while r < samples.n_samples {
        var d: i32 = 0
        while d < samples.n_dims {
            let flat = r * samples.n_dims + d
            if d == dim_i || d == dim_j {
                cij[flat] = samples.matrix_b[flat]
            } else {
                cij[flat] = samples.matrix_a[flat]
            }
            d = d + 1
        }
        r = r + 1
    }
    return cij
}

fn saltelli_eval_row(matrix: &[f64; 5000], row: i32, n_dims: i32, model: fn([f64; 10]) -> f64) -> f64 {
    var input: [f64; 10] = [0.0; 10]
    var d: i32 = 0
    while d < n_dims {
        if d < 10 {
            input[d] = matrix[row * n_dims + d]
        }
        d = d + 1
    }
    return model(input)
}

fn saltelli_first_order(
    samples: &SaltelliSamples,
    model_outputs_a: &[f64; 1000],
    model_outputs_b: &[f64; 1000],
    model_outputs_ci: &[f64; 1000]
) -> f64 {
    let n = samples.n_samples
    if n < 2 { return 0.0 }
    let nf = n as f64

    var sum_all: f64 = 0.0
    var sum_sq_all: f64 = 0.0
    var k: i32 = 0
    while k < n {
        sum_all = sum_all + model_outputs_a[k] + model_outputs_b[k]
        sum_sq_all = sum_sq_all + model_outputs_a[k] * model_outputs_a[k]
                                + model_outputs_b[k] * model_outputs_b[k]
        k = k + 1
    }
    let mean_y = sum_all / (2.0 * nf)
    let var_y = sum_sq_all / (2.0 * nf) - mean_y * mean_y
    if var_y < 1.0e-15 { return 0.0 }

    var numerator: f64 = 0.0
    k = 0
    while k < n {
        numerator = numerator + model_outputs_b[k] * (model_outputs_ci[k] - model_outputs_a[k])
        k = k + 1
    }
    numerator = numerator / nf
    let si = numerator / var_y
    return max_f64(0.0, min_f64(1.0, si))
}

fn saltelli_total_order(
    samples: &SaltelliSamples,
    model_outputs_a: &[f64; 1000],
    model_outputs_ci: &[f64; 1000]
) -> f64 {
    let n = samples.n_samples
    if n < 2 { return 0.0 }
    let nf = n as f64

    var sum_a: f64 = 0.0
    var sum_sq_a: f64 = 0.0
    var k: i32 = 0
    while k < n {
        sum_a = sum_a + model_outputs_a[k]
        sum_sq_a = sum_sq_a + model_outputs_a[k] * model_outputs_a[k]
        k = k + 1
    }
    let mean_a = sum_a / nf
    let var_y = sum_sq_a / nf - mean_a * mean_a
    if var_y < 1.0e-15 { return 0.0 }

    var numerator: f64 = 0.0
    k = 0
    while k < n {
        let diff = model_outputs_a[k] - model_outputs_ci[k]
        numerator = numerator + diff * diff
        k = k + 1
    }
    numerator = numerator / (2.0 * nf)
    let sti = numerator / var_y
    return max_f64(0.0, min_f64(1.0, sti))
}

fn saltelli_second_order(
    samples: &SaltelliSamples,
    model_outputs_a: &[f64; 1000],
    model_outputs_b: &[f64; 1000],
    model_outputs_ci: &[f64; 1000],
    model_outputs_cj: &[f64; 1000],
    model_outputs_cij: &[f64; 1000],
    s_i: f64,
    s_j: f64
) -> f64 {
    let n = samples.n_samples
    if n < 2 { return 0.0 }
    let nf = n as f64

    var sum_all: f64 = 0.0
    var sum_sq_all: f64 = 0.0
    var k: i32 = 0
    while k < n {
        sum_all = sum_all + model_outputs_a[k] + model_outputs_b[k]
        sum_sq_all = sum_sq_all + model_outputs_a[k] * model_outputs_a[k]
                                + model_outputs_b[k] * model_outputs_b[k]
        k = k + 1
    }
    let mean_y = sum_all / (2.0 * nf)
    let var_y = sum_sq_all / (2.0 * nf) - mean_y * mean_y
    if var_y < 1.0e-15 { return 0.0 }

    var numerator_ij: f64 = 0.0
    k = 0
    while k < n {
        numerator_ij = numerator_ij + model_outputs_b[k] * (model_outputs_cij[k] - model_outputs_a[k])
        k = k + 1
    }
    let s_ij_closed = (numerator_ij / nf) / var_y
    let s_ij = s_ij_closed - s_i - s_j
    return max_f64(-0.05, min_f64(1.0, s_ij))
}

fn saltelli_expected_evals(n_samples: i32, n_dims: i32) -> i32 {
    let base = n_samples * (n_dims + 2)
    let n_pairs = n_dims * (n_dims - 1) / 2
    let second = n_samples * n_pairs
    return base + second
}

// ============================================================================
// TEST 1: Linear model  f(x1, x2) = 2*x1 + x2
// ============================================================================
// For uniform inputs on [0,1]:
//   Var(2*x1) = 4 * Var(x1) = 4/12 = 1/3
//   Var(x2)   = 1/12
//   Total Var = 5/12
//   S1 = (1/3) / (5/12) = 4/5 = 0.8
//   S2 = (1/12) / (5/12) = 1/5 = 0.2
//   S12 = 0  (no interaction in a linear model)

fn linear_model(x: [f64; 10]) -> f64 {
    return 2.0 * x[0] + x[1]
}

fn test_linear_model() -> bool {
    let n_samples: i32 = 512
    let samples = saltelli_generate(n_samples, 2, 42)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    // Evaluate on A and B
    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 2, linear_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 2, linear_model)
        k = k + 1
    }

    // C_0: A with column 0 from B
    let c0 = saltelli_build_ci(&samples, 0)
    var out_c0: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 2, linear_model)
        k = k + 1
    }

    // C_1: A with column 1 from B
    let c1 = saltelli_build_ci(&samples, 1)
    var out_c1: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c1[k] = saltelli_eval_row(&c1, k, 2, linear_model)
        k = k + 1
    }

    // C_01: A with columns 0 and 1 from B (= B itself for 2D)
    let c01 = saltelli_build_cij(&samples, 0, 1)
    var out_c01: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c01[k] = saltelli_eval_row(&c01, k, 2, linear_model)
        k = k + 1
    }

    // Compute indices
    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)

    let s12 = saltelli_second_order(
        &samples, &out_a, &out_b, &out_c0, &out_c1, &out_c01, s1, s2
    )

    // Check S1 ~ 0.8 within 15% tolerance
    let tol: f64 = 0.15
    var ok = true

    if abs_f64(s1 - 0.8) > tol { ok = false }
    if abs_f64(s2 - 0.2) > tol { ok = false }

    // Total order should approximately equal first order for linear model
    if abs_f64(st1 - 0.8) > tol { ok = false }
    if abs_f64(st2 - 0.2) > tol { ok = false }

    // Interaction should be near zero
    if abs_f64(s12) > 0.1 { ok = false }

    return ok
}

// ============================================================================
// TEST 2: Pure interaction model  f(x1, x2) = x1 * x2
// ============================================================================
// For uniform inputs on [0,1]:
//   E[x1*x2] = 1/4, E[(x1*x2)^2] = 1/9
//   Var(x1*x2) = 1/9 - 1/16 = 7/144
//   V1 = Var_x1(E[x1*x2 | x1]) = Var_x1(x1/2) = 1/48
//   V2 = Var_x2(E[x1*x2 | x2]) = Var_x2(x2/2) = 1/48
//   S1 = S2 = (1/48) / (7/144) = 3/7 ~ 0.4286
//   S12 = 1 - S1 - S2 = 1/7 ~ 0.1429
//
// Note: S1 and S2 are NOT zero for x1*x2 on [0,1] -- the analytical values
// are 3/7 each. The total-order indices are S_T1 = S_T2 = S1 + S12 = 4/7.

fn interaction_model(x: [f64; 10]) -> f64 {
    return x[0] * x[1]
}

fn test_interaction_model() -> bool {
    let n_samples: i32 = 512
    let samples = saltelli_generate(n_samples, 2, 137)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 2, interaction_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 2, interaction_model)
        k = k + 1
    }

    let c0 = saltelli_build_ci(&samples, 0)
    var out_c0: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 2, interaction_model)
        k = k + 1
    }

    let c1 = saltelli_build_ci(&samples, 1)
    var out_c1: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c1[k] = saltelli_eval_row(&c1, k, 2, interaction_model)
        k = k + 1
    }

    let c01 = saltelli_build_cij(&samples, 0, 1)
    var out_c01: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c01[k] = saltelli_eval_row(&c01, k, 2, interaction_model)
        k = k + 1
    }

    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)

    let s12 = saltelli_second_order(
        &samples, &out_a, &out_b, &out_c0, &out_c1, &out_c01, s1, s2
    )

    // Analytical: S1 = S2 = 3/7 ~ 0.4286
    let tol: f64 = 0.15
    var ok = true

    // First-order indices should be moderate (not zero)
    if s1 < 0.15 { ok = false }
    if s2 < 0.15 { ok = false }

    // Total-order should be larger than first-order (interactions present)
    if st1 < s1 - 0.05 { ok = false }
    if st2 < s2 - 0.05 { ok = false }

    // Second-order interaction should be positive (some interaction variance)
    // Analytical S12 = 1/7 ~ 0.143
    // Allow wide tolerance due to quasi-random noise
    if s12 < -0.05 { ok = false }

    return ok
}

// ============================================================================
// TEST 3: Ishigami function (classic sensitivity analysis benchmark)
// ============================================================================
// f(x1, x2, x3) = sin(x1) + 7*sin^2(x2) + 0.1*x3^4*sin(x1)
// where x_i ~ Uniform[-pi, pi]
//
// Analytical Sobol' indices (a=7, b=0.1):
//   S1 ~ 0.3139,  S_T1 ~ 0.5576
//   S2 ~ 0.4424,  S_T2 ~ 0.4424
//   S3 ~ 0.0,     S_T3 ~ 0.2437
//   S13 ~ 0.2437 (only nonzero second-order interaction)

fn ishigami_model(x: [f64; 10]) -> f64 {
    // Map [0,1] -> [-pi, pi]
    let pi = 3.14159265358979323846
    let x1 = x[0] * 2.0 * pi - pi
    let x2 = x[1] * 2.0 * pi - pi
    let x3 = x[2] * 2.0 * pi - pi

    let sin_x1 = sin(x1)
    let sin_x2 = sin(x2)
    let x3_4 = x3 * x3 * x3 * x3

    return sin_x1 + 7.0 * sin_x2 * sin_x2 + 0.1 * x3_4 * sin_x1
}

fn test_ishigami() -> bool {
    let n_samples: i32 = 800
    let samples = saltelli_generate(n_samples, 3, 271)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    // Evaluate on A and B
    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 3, ishigami_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 3, ishigami_model)
        k = k + 1
    }

    // Build C_i outputs for each dimension
    let c0 = saltelli_build_ci(&samples, 0)
    var out_c0: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 3, ishigami_model)
        k = k + 1
    }

    let c1 = saltelli_build_ci(&samples, 1)
    var out_c1: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c1[k] = saltelli_eval_row(&c1, k, 3, ishigami_model)
        k = k + 1
    }

    let c2 = saltelli_build_ci(&samples, 2)
    var out_c2: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c2[k] = saltelli_eval_row(&c2, k, 3, ishigami_model)
        k = k + 1
    }

    // First-order indices
    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let s3 = saltelli_first_order(&samples, &out_a, &out_b, &out_c2)

    // Total-order indices
    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)
    let st3 = saltelli_total_order(&samples, &out_a, &out_c2)

    // Validate with 15% tolerance (Monte Carlo variance)
    let tol: f64 = 0.15
    var ok = true

    // S1 ~ 0.314: x1 has moderate first-order influence
    if abs_f64(s1 - 0.314) > tol { ok = false }

    // S2 ~ 0.442: x2 has the largest first-order influence
    if abs_f64(s2 - 0.442) > tol { ok = false }

    // S3 ~ 0.0: x3 has negligible first-order effect
    if s3 > 0.15 { ok = false }

    // S_T1 ~ 0.558: x1 has large total effect (via interaction with x3)
    if abs_f64(st1 - 0.558) > tol { ok = false }

    // S_T2 ~ 0.442: x2 total = first (no interactions)
    if abs_f64(st2 - 0.442) > tol { ok = false }

    // S_T3 ~ 0.244: x3 only acts through interaction with x1
    if abs_f64(st3 - 0.244) > tol { ok = false }

    return ok
}

// ============================================================================
// TEST 4: N(2d+2) efficiency verification
// ============================================================================
// For d=3, the expected evaluations are:
//   Base:   N * (3 + 2)   = 5N   (A, B, C_0, C_1, C_2)
//   Pairs:  N * C(3,2)    = 3N   (C_01, C_02, C_12)
//   Total:  8N
// Canonical formula: N(2d+2) = N * 8 = 8N  (matches for d=3)

fn test_n2d2_efficiency() -> bool {
    let n: i32 = 100
    let d: i32 = 3

    // Expected: N * (d + 2) + N * d*(d-1)/2 = 100*5 + 100*3 = 800
    let expected = saltelli_expected_evals(n, d)

    // N(2d+2) = 100 * 8 = 800
    let canonical = n * (2 * d + 2)

    // For d=3, the exact formula and the N(2d+2) approximation match exactly
    if expected != canonical { return false }

    // Also check d=2: N*(2+2) + N*1 = 5N; N(2*2+2) = 6N
    // These differ because N(2d+2) is an approximation
    let expected_2d = saltelli_expected_evals(n, 2)
    let exact_2d = n * (2 + 2) + n * 1  // = 500
    if expected_2d != exact_2d { return false }

    // Check d=1: N*(1+2) + N*0 = 3N
    let expected_1d = saltelli_expected_evals(n, 1)
    if expected_1d != n * 3 { return false }

    return true
}

// ============================================================================
// TEST 5: Matrix construction correctness
// ============================================================================
// Verify that C_i and C_ij matrices are built correctly from A and B.

fn test_matrix_construction() -> bool {
    // Small test: 3 samples, 3 dims
    let samples = saltelli_generate(3, 3, 99)

    // Build C_1: should equal A everywhere except column 1
    let c1 = saltelli_build_ci(&samples, 1)

    var ok = true
    var i: i32 = 0
    while i < 3 {
        var d: i32 = 0
        while d < 3 {
            let flat = i * 3 + d
            if d == 1 {
                // Column 1 should come from B
                if abs_f64(c1[flat] - samples.matrix_b[flat]) > 1.0e-12 { ok = false }
            } else {
                // Other columns should come from A
                if abs_f64(c1[flat] - samples.matrix_a[flat]) > 1.0e-12 { ok = false }
            }
            d = d + 1
        }
        i = i + 1
    }

    // Build C_02: should equal A everywhere except columns 0 and 2
    let c02 = saltelli_build_cij(&samples, 0, 2)

    i = 0
    while i < 3 {
        var d: i32 = 0
        while d < 3 {
            let flat = i * 3 + d
            if d == 0 || d == 2 {
                if abs_f64(c02[flat] - samples.matrix_b[flat]) > 1.0e-12 { ok = false }
            } else {
                if abs_f64(c02[flat] - samples.matrix_a[flat]) > 1.0e-12 { ok = false }
            }
            d = d + 1
        }
        i = i + 1
    }

    return ok
}

// ============================================================================
// TEST 6: Samples are in [0, 1] range
// ============================================================================

fn test_sample_range() -> bool {
    let samples = saltelli_generate(100, 4, 7)

    var ok = true
    var i: i32 = 0
    while i < 100 {
        var d: i32 = 0
        while d < 4 {
            let flat = i * 4 + d
            if samples.matrix_a[flat] < 0.0 || samples.matrix_a[flat] > 1.0 { ok = false }
            if samples.matrix_b[flat] < 0.0 || samples.matrix_b[flat] > 1.0 { ok = false }
            d = d + 1
        }
        i = i + 1
    }

    return ok
}

// ============================================================================
// TEST 7: Additive model (no interactions, indices should sum to 1)
// ============================================================================
// f(x1, x2, x3) = x1 + 2*x2 + 3*x3
// Var = 1/12 + 4/12 + 9/12 = 14/12
// S1 = 1/14, S2 = 4/14, S3 = 9/14
// All S_ij = 0

fn additive_model(x: [f64; 10]) -> f64 {
    return x[0] + 2.0 * x[1] + 3.0 * x[2]
}

fn test_additive_model() -> bool {
    let n_samples: i32 = 512
    let samples = saltelli_generate(n_samples, 3, 53)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 3, additive_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 3, additive_model)
        k = k + 1
    }

    // C_i for each dimension
    let c0 = saltelli_build_ci(&samples, 0)
    let c1 = saltelli_build_ci(&samples, 1)
    let c2 = saltelli_build_ci(&samples, 2)

    var out_c0: [f64; 1000] = [0.0; 1000]
    var out_c1: [f64; 1000] = [0.0; 1000]
    var out_c2: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 3, additive_model)
        out_c1[k] = saltelli_eval_row(&c1, k, 3, additive_model)
        out_c2[k] = saltelli_eval_row(&c2, k, 3, additive_model)
        k = k + 1
    }

    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let s3 = saltelli_first_order(&samples, &out_a, &out_b, &out_c2)

    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)
    let st3 = saltelli_total_order(&samples, &out_a, &out_c2)

    let tol: f64 = 0.15
    var ok = true

    // S1 ~ 1/14 ~ 0.071
    if abs_f64(s1 - 0.071) > tol { ok = false }

    // S2 ~ 4/14 ~ 0.286
    if abs_f64(s2 - 0.286) > tol { ok = false }

    // S3 ~ 9/14 ~ 0.643
    if abs_f64(s3 - 0.643) > tol { ok = false }

    // For an additive model, total order should equal first order
    if abs_f64(st1 - s1) > 0.1 { ok = false }
    if abs_f64(st2 - s2) > 0.1 { ok = false }
    if abs_f64(st3 - s3) > 0.1 { ok = false }

    // Sum of first-order indices should be close to 1 (no interactions)
    let s_sum = s1 + s2 + s3
    if abs_f64(s_sum - 1.0) > 0.2 { ok = false }

    return ok
}

// ============================================================================
// MAIN: run all tests
// ============================================================================

fn main() -> i32 {
    var failures: i32 = 0

    if !test_matrix_construction() { failures = failures + 1 }
    if !test_sample_range() { failures = failures + 1 }
    if !test_n2d2_efficiency() { failures = failures + 1 }
    if !test_linear_model() { failures = failures + 1 }
    if !test_interaction_model() { failures = failures + 1 }
    if !test_additive_model() { failures = failures + 1 }
    if !test_ishigami() { failures = failures + 1 }

    return failures
}

//@ run-pass
// test_diffgeo.sio -- Tests for the differential geometry module
//
// Self-contained test suite for metric tensors, Christoffel symbols,
// Riemann curvature, Gaussian curvature, geodesic integration,
// parallel transport, and index raising/lowering. All helpers and
// functions copied from stdlib/math/diffgeo.sio.
//
// Tests:
//  1.  Euclidean metric is identity: diag(1,1,1)
//  2.  Metric inverse of identity: g^{-1} = g for Euclidean
//  3.  Flat space Christoffel symbols = 0
//  4.  Flat space Riemann tensor = 0
//  5.  Sphere 2D Gaussian curvature = 1 (unit sphere)
//  6.  Sphere metric at equator: g = diag(1, 1)
//  7.  Schwarzschild metric at r=10: g_tt ~ -0.8, g_rr ~ 1.25
//  8.  Geodesic in flat space is straight line
//  9.  Parallel transport preserves norm in Euclidean space
// 10.  Hyperbolic plane curvature = -1
// 11.  Metric determinant of sphere: det(g) = sin^2(theta) at theta=pi/4
// 12.  Raise and lower index roundtrip

// ============================================================================
// HELPERS (copied from diffgeo.sio -- tests must be self-contained)
// ============================================================================

fn dg_abs(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }
fn dg_max(a: f64, b: f64) -> f64 { if a > b { a } else { b } }

fn dg_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 24 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn dg_sin(x: f64) -> f64 with Mut, Div, Panic {
    var a = x
    let tp = 6.28318530717958647692
    while a >= tp { a = a - tp }
    while a < 0.0 { a = a + tp }
    if a > 3.14159265358979323846 { a = a - tp }
    let a2 = a * a
    var sum = a
    var term = a
    var n = 1
    while n < 20 { term = 0.0 - term * a2 / ((2 * n) * (2 * n + 1)) as f64; sum = sum + term; n = n + 1 }
    sum
}

fn dg_cos(x: f64) -> f64 with Mut, Div, Panic {
    dg_sin(x + 1.57079632679489661923)
}

fn dg_exp(x: f64) -> f64 with Mut, Div, Panic {
    if x > 500.0 { return 1.0e200 }
    if x < -500.0 { return 0.0 }
    let ln2 = 0.6931471805599453
    var kf = x / ln2
    var k: i32 = 0
    if kf >= 0.0 { k = kf as i32 } else { k = (kf as i32) - 1 }
    let r = x - (k as f64) * ln2
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n < 25 { term = term * r / (n as f64); sum = sum + term; n = n + 1 }
    var result = sum
    if k >= 0 { var i = 0; while i < k { result = result * 2.0; i = i + 1 } }
    else { var i = 0; while i < (0 - k) { result = result / 2.0; i = i + 1 } }
    result
}

fn dg_ln(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    if x == 1.0 { return 0.0 }
    var m = x
    var e = 0
    while m >= 2.0 { m = m / 2.0; e = e + 1 }
    while m < 0.5 { m = m * 2.0; e = e - 1 }
    let t = (m - 1.0) / (m + 1.0)
    let t2 = t * t
    var sum = t
    var term = t
    var k = 1
    while k < 30 { term = term * t2; sum = sum + term / ((2 * k + 1) as f64); k = k + 1 }
    2.0 * sum + (e as f64) * 0.6931471805599453
}

fn dg_pi() -> f64 { 3.14159265358979323846 }

// ============================================================================
// STRUCTS (copied from diffgeo.sio)
// ============================================================================

struct Metric4 { g: [f64; 16], dim: i32 }

struct Christoffel4 { gamma: [f64; 64], dim: i32 }

struct RiemannTensor { R: [f64; 256], dim: i32 }

struct RicciTensor { Ric: [f64; 16], scalar: f64, dim: i32 }

struct GeodesicState { x: [f64; 4], v: [f64; 4], dim: i32, tau: f64 }

struct GeodesicPath { x: [f64; 4096], v: [f64; 4096], tau: [f64; 1024], n_steps: i32, dim: i32 }

// ============================================================================
// METRIC OPERATIONS (copied from diffgeo.sio)
// ============================================================================

fn metric_inverse(g: &[f64; 16], dim: i32, g_inv: &![f64; 16]) with Mut, Div, Panic {
    var work: [f64; 32] = [0.0; 32]

    var i = 0
    while i < dim {
        var j = 0
        while j < dim {
            work[i * 2 * dim + j] = g[i * dim + j]
            j = j + 1
        }
        work[i * 2 * dim + dim + i] = 1.0
        i = i + 1
    }

    var col = 0
    while col < dim {
        var max_val = dg_abs(work[col * 2 * dim + col])
        var max_row = col
        var row = col + 1
        while row < dim {
            let v = dg_abs(work[row * 2 * dim + col])
            if v > max_val { max_val = v; max_row = row }
            row = row + 1
        }

        if max_row != col {
            var j = 0
            while j < 2 * dim {
                let tmp = work[col * 2 * dim + j]
                work[col * 2 * dim + j] = work[max_row * 2 * dim + j]
                work[max_row * 2 * dim + j] = tmp
                j = j + 1
            }
        }

        let pivot = work[col * 2 * dim + col]
        if dg_abs(pivot) < 1.0e-30 {
            i = 0
            while i < 16 { g_inv[i] = 0.0; i = i + 1 }
            i = 0
            while i < dim { g_inv[i * dim + i] = 1.0; i = i + 1 }
            return
        }

        let inv_pivot = 1.0 / pivot
        var j = 0
        while j < 2 * dim {
            work[col * 2 * dim + j] = work[col * 2 * dim + j] * inv_pivot
            j = j + 1
        }

        row = 0
        while row < dim {
            if row != col {
                let factor = work[row * 2 * dim + col]
                j = 0
                while j < 2 * dim {
                    work[row * 2 * dim + j] = work[row * 2 * dim + j] - factor * work[col * 2 * dim + j]
                    j = j + 1
                }
            }
            row = row + 1
        }
        col = col + 1
    }

    i = 0
    while i < 16 { g_inv[i] = 0.0; i = i + 1 }
    i = 0
    while i < dim {
        var j = 0
        while j < dim {
            g_inv[i * dim + j] = work[i * 2 * dim + dim + j]
            j = j + 1
        }
        i = i + 1
    }
}

fn metric_det(g: &[f64; 16], dim: i32) -> f64 with Mut, Div, Panic {
    if dim == 1 { return g[0] }

    if dim == 2 {
        return g[0] * g[3] - g[1] * g[2]
    }

    if dim == 3 {
        let a = g[0]; let b = g[1]; let c = g[2]
        let d = g[3]; let e = g[4]; let f = g[5]
        let h = g[6]; let i = g[7]; let j = g[8]
        return a * (e * j - f * i) - b * (d * j - f * h) + c * (d * i - e * h)
    }

    var A: [f64; 16] = [0.0; 16]
    var k = 0
    while k < 16 { A[k] = g[k]; k = k + 1 }

    var det = 1.0
    var col = 0
    while col < dim {
        var max_val = dg_abs(A[col * dim + col])
        var max_row = col
        var row = col + 1
        while row < dim {
            let v = dg_abs(A[row * dim + col])
            if v > max_val { max_val = v; max_row = row }
            row = row + 1
        }
        if max_row != col {
            var j = 0
            while j < dim {
                let tmp = A[col * dim + j]
                A[col * dim + j] = A[max_row * dim + j]
                A[max_row * dim + j] = tmp
                j = j + 1
            }
            det = 0.0 - det
        }

        let pivot = A[col * dim + col]
        if dg_abs(pivot) < 1.0e-30 { return 0.0 }
        det = det * pivot

        row = col + 1
        while row < dim {
            let factor = A[row * dim + col] / pivot
            var j = col + 1
            while j < dim {
                A[row * dim + j] = A[row * dim + j] - factor * A[col * dim + j]
                j = j + 1
            }
            row = row + 1
        }
        col = col + 1
    }
    det
}

fn metric_raise_index(g_inv: &[f64; 16], v_lower: &[f64; 4], dim: i32, v_upper: &![f64; 4]) with Mut, Div, Panic {
    var i = 0
    while i < dim {
        var s = 0.0
        var j = 0
        while j < dim {
            s = s + g_inv[i * dim + j] * v_lower[j]
            j = j + 1
        }
        v_upper[i] = s
        i = i + 1
    }
    while i < 4 { v_upper[i] = 0.0; i = i + 1 }
}

fn metric_lower_index(g: &[f64; 16], v_upper: &[f64; 4], dim: i32, v_lower: &![f64; 4]) with Mut, Div, Panic {
    var i = 0
    while i < dim {
        var s = 0.0
        var j = 0
        while j < dim {
            s = s + g[i * dim + j] * v_upper[j]
            j = j + 1
        }
        v_lower[i] = s
        i = i + 1
    }
    while i < 4 { v_lower[i] = 0.0; i = i + 1 }
}

// ============================================================================
// CHRISTOFFEL SYMBOLS (copied from diffgeo.sio)
// ============================================================================

fn christoffel_from_metric(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                           x: &[f64; 4], dim: i32,
                           gamma: &!Christoffel4) with Mut, Div, Panic {
    let h = 1.0e-6
    gamma.dim = dim

    var idx = 0
    while idx < 64 { gamma.gamma[idx] = 0.0; idx = idx + 1 }

    var g0: [f64; 16] = [0.0; 16]
    metric_fn(x, dim, &!g0)

    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g0, dim, &!g_inv)

    var dg: [f64; 256] = [0.0; 256]

    var m = 0
    while m < dim {
        var xp: [f64; 4] = [0.0; 4]
        var xm: [f64; 4] = [0.0; 4]
        var c = 0
        while c < 4 { xp[c] = x[c]; xm[c] = x[c]; c = c + 1 }
        xp[m] = x[m] + h
        xm[m] = x[m] - h

        var gp: [f64; 16] = [0.0; 16]
        var gm: [f64; 16] = [0.0; 16]
        metric_fn(&xp, dim, &!gp)
        metric_fn(&xm, dim, &!gm)

        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                dg[m * dim * dim + i * dim + j] = (gp[i * dim + j] - gm[i * dim + j]) / (2.0 * h)
                j = j + 1
            }
            i = i + 1
        }
        m = m + 1
    }

    var k = 0
    while k < dim {
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                var s = 0.0
                var l = 0
                while l < dim {
                    let term1 = dg[j * dim * dim + l * dim + i]
                    let term2 = dg[i * dim * dim + l * dim + j]
                    let term3 = dg[l * dim * dim + i * dim + j]
                    s = s + g_inv[k * dim + l] * (term1 + term2 - term3)
                    l = l + 1
                }
                gamma.gamma[k * dim * dim + i * dim + j] = 0.5 * s
                j = j + 1
            }
            i = i + 1
        }
        k = k + 1
    }
}

// ============================================================================
// RIEMANN CURVATURE TENSOR (copied from diffgeo.sio)
// ============================================================================

fn riemann_tensor(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                  x: &[f64; 4], dim: i32,
                  R: &!RiemannTensor) with Mut, Div, Panic {
    let h = 1.0e-5
    R.dim = dim

    var idx = 0
    while idx < 256 { R.R[idx] = 0.0; idx = idx + 1 }

    var gamma0: Christoffel4 = Christoffel4 { gamma: [0.0; 64], dim: dim }
    christoffel_from_metric(metric_fn, x, dim, &!gamma0)

    var d_gamma: [f64; 256] = [0.0; 256]

    var m = 0
    while m < dim {
        var xp: [f64; 4] = [0.0; 4]
        var xm: [f64; 4] = [0.0; 4]
        var c = 0
        while c < 4 { xp[c] = x[c]; xm[c] = x[c]; c = c + 1 }
        xp[m] = x[m] + h
        xm[m] = x[m] - h

        var gp: Christoffel4 = Christoffel4 { gamma: [0.0; 64], dim: dim }
        var gm: Christoffel4 = Christoffel4 { gamma: [0.0; 64], dim: dim }
        christoffel_from_metric(metric_fn, &xp, dim, &!gp)
        christoffel_from_metric(metric_fn, &xm, dim, &!gm)

        var k = 0
        while k < dim {
            var a = 0
            while a < dim {
                var b = 0
                while b < dim {
                    let gp_val = gp.gamma[k * dim * dim + a * dim + b]
                    let gm_val = gm.gamma[k * dim * dim + a * dim + b]
                    d_gamma[m * dim * dim * dim + k * dim * dim + a * dim + b] = (gp_val - gm_val) / (2.0 * h)
                    b = b + 1
                }
                a = a + 1
            }
            k = k + 1
        }
        m = m + 1
    }

    var k = 0
    while k < dim {
        var l = 0
        while l < dim {
            var i = 0
            while i < dim {
                var j = 0
                while j < dim {
                    let di_Gkjl = d_gamma[i * dim * dim * dim + k * dim * dim + j * dim + l]
                    let dj_Gkil = d_gamma[j * dim * dim * dim + k * dim * dim + i * dim + l]

                    var quad1 = 0.0
                    var quad2 = 0.0
                    var mm = 0
                    while mm < dim {
                        quad1 = quad1 + gamma0.gamma[k * dim * dim + i * dim + mm] * gamma0.gamma[mm * dim * dim + j * dim + l]
                        quad2 = quad2 + gamma0.gamma[k * dim * dim + j * dim + mm] * gamma0.gamma[mm * dim * dim + i * dim + l]
                        mm = mm + 1
                    }

                    R.R[k * dim * dim * dim + l * dim * dim + i * dim + j] = di_Gkjl - dj_Gkil + quad1 - quad2
                    j = j + 1
                }
                i = i + 1
            }
            l = l + 1
        }
        k = k + 1
    }
}

// ============================================================================
// RICCI TENSOR AND SCALAR CURVATURE (copied from diffgeo.sio)
// ============================================================================

fn ricci_tensor(R_in: &RiemannTensor, result: &!RicciTensor) with Mut, Div, Panic {
    let dim = R_in.dim
    result.dim = dim
    result.scalar = 0.0

    var i = 0
    while i < 16 { result.Ric[i] = 0.0; i = i + 1 }

    i = 0
    while i < dim {
        var j = 0
        while j < dim {
            var s = 0.0
            var k = 0
            while k < dim {
                s = s + R_in.R[k * dim * dim * dim + i * dim * dim + k * dim + j]
                k = k + 1
            }
            result.Ric[i * dim + j] = s
            j = j + 1
        }
        i = i + 1
    }
}

fn ricci_with_scalar(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                     x: &[f64; 4], dim: i32,
                     result: &!RicciTensor) with Mut, Div, Panic {
    var Riem: RiemannTensor = RiemannTensor { R: [0.0; 256], dim: dim }
    riemann_tensor(metric_fn, x, dim, &!Riem)

    ricci_tensor(&Riem, result)

    var g0: [f64; 16] = [0.0; 16]
    metric_fn(x, dim, &!g0)
    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g0, dim, &!g_inv)

    var scalar = 0.0
    var i = 0
    while i < dim {
        var j = 0
        while j < dim {
            scalar = scalar + g_inv[i * dim + j] * result.Ric[i * dim + j]
            j = j + 1
        }
        i = i + 1
    }
    result.scalar = scalar
}

fn gauss_curvature_2d(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                      x: &[f64; 4]) -> f64 with Mut, Div, Panic {
    let dim = 2
    var ric: RicciTensor = RicciTensor { Ric: [0.0; 16], scalar: 0.0, dim: dim }
    ricci_with_scalar(metric_fn, x, dim, &!ric)
    ric.scalar / 2.0
}

// ============================================================================
// GEODESIC EQUATIONS (copied from diffgeo.sio)
// ============================================================================

fn geodesic_rhs(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                st: &GeodesicState,
                dx: &![f64; 4], dv: &![f64; 4]) with Mut, Div, Panic {
    let dim = st.dim

    var i = 0
    while i < 4 { dx[i] = 0.0; dv[i] = 0.0; i = i + 1 }
    i = 0
    while i < dim { dx[i] = st.v[i]; i = i + 1 }

    var gamma: Christoffel4 = Christoffel4 { gamma: [0.0; 64], dim: dim }
    christoffel_from_metric(metric_fn, &st.x, dim, &!gamma)

    var k = 0
    while k < dim {
        var s = 0.0
        i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * st.v[i] * st.v[j]
                j = j + 1
            }
            i = i + 1
        }
        dv[k] = 0.0 - s
        k = k + 1
    }
}

fn geodesic_step(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                 st: &!GeodesicState, dtau: f64) with Mut, Div, Panic {
    let dim = st.dim

    var dx1: [f64; 4] = [0.0; 4]
    var dv1: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, st, &!dx1, &!dv1)

    var s2: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], dim: dim, tau: st.tau + dtau / 2.0 }
    var c = 0
    while c < dim {
        s2.x[c] = st.x[c] + 0.5 * dtau * dx1[c]
        s2.v[c] = st.v[c] + 0.5 * dtau * dv1[c]
        c = c + 1
    }

    var dx2: [f64; 4] = [0.0; 4]
    var dv2: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, &s2, &!dx2, &!dv2)

    var s3: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], dim: dim, tau: st.tau + dtau / 2.0 }
    c = 0
    while c < dim {
        s3.x[c] = st.x[c] + 0.5 * dtau * dx2[c]
        s3.v[c] = st.v[c] + 0.5 * dtau * dv2[c]
        c = c + 1
    }

    var dx3: [f64; 4] = [0.0; 4]
    var dv3: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, &s3, &!dx3, &!dv3)

    var s4: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], dim: dim, tau: st.tau + dtau }
    c = 0
    while c < dim {
        s4.x[c] = st.x[c] + dtau * dx3[c]
        s4.v[c] = st.v[c] + dtau * dv3[c]
        c = c + 1
    }

    var dx4: [f64; 4] = [0.0; 4]
    var dv4: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, &s4, &!dx4, &!dv4)

    c = 0
    while c < dim {
        st.x[c] = st.x[c] + dtau / 6.0 * (dx1[c] + 2.0 * dx2[c] + 2.0 * dx3[c] + dx4[c])
        st.v[c] = st.v[c] + dtau / 6.0 * (dv1[c] + 2.0 * dv2[c] + 2.0 * dv3[c] + dv4[c])
        c = c + 1
    }
    st.tau = st.tau + dtau
}

fn geodesic_integrate(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                      x0: &[f64; 4], v0: &[f64; 4], dim: i32,
                      tau_end: f64, n_steps: i32,
                      path: &!GeodesicPath) with Mut, Div, Panic {
    path.dim = dim
    path.n_steps = n_steps

    var z = 0
    while z < 4096 { path.x[z] = 0.0; path.v[z] = 0.0; z = z + 1 }
    z = 0
    while z < 1024 { path.tau[z] = 0.0; z = z + 1 }

    let dtau = tau_end / (n_steps as f64)

    var state: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], dim: dim, tau: 0.0 }
    var c = 0
    while c < dim { state.x[c] = x0[c]; state.v[c] = v0[c]; c = c + 1 }

    c = 0
    while c < dim {
        path.x[0 * dim + c] = state.x[c]
        path.v[0 * dim + c] = state.v[c]
        c = c + 1
    }
    path.tau[0] = 0.0

    var step = 1
    while step <= n_steps {
        geodesic_step(metric_fn, &!state, dtau)

        if step < 1024 {
            path.tau[step] = state.tau
            c = 0
            while c < dim {
                path.x[step * dim + c] = state.x[c]
                path.v[step * dim + c] = state.v[c]
                c = c + 1
            }
        }
        step = step + 1
    }
}

// ============================================================================
// PARALLEL TRANSPORT (copied from diffgeo.sio)
// ============================================================================

fn parallel_transport_step(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                           x: &[f64; 4], v: &[f64; 4],
                           w: &![f64; 4], dim: i32, dtau: f64) with Mut, Div, Panic {
    var gamma: Christoffel4 = Christoffel4 { gamma: [0.0; 64], dim: dim }
    christoffel_from_metric(metric_fn, x, dim, &!gamma)

    var k1: [f64; 4] = [0.0; 4]
    var k = 0
    while k < dim {
        var s = 0.0
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * v[i] * w[j]
                j = j + 1
            }
            i = i + 1
        }
        k1[k] = 0.0 - s
        k = k + 1
    }

    var w2: [f64; 4] = [0.0; 4]
    var c = 0
    while c < dim { w2[c] = w[c] + 0.5 * dtau * k1[c]; c = c + 1 }
    var k2: [f64; 4] = [0.0; 4]
    k = 0
    while k < dim {
        var s = 0.0
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * v[i] * w2[j]
                j = j + 1
            }
            i = i + 1
        }
        k2[k] = 0.0 - s
        k = k + 1
    }

    var w3: [f64; 4] = [0.0; 4]
    c = 0
    while c < dim { w3[c] = w[c] + 0.5 * dtau * k2[c]; c = c + 1 }
    var k3: [f64; 4] = [0.0; 4]
    k = 0
    while k < dim {
        var s = 0.0
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * v[i] * w3[j]
                j = j + 1
            }
            i = i + 1
        }
        k3[k] = 0.0 - s
        k = k + 1
    }

    var w4: [f64; 4] = [0.0; 4]
    c = 0
    while c < dim { w4[c] = w[c] + dtau * k3[c]; c = c + 1 }
    var k4: [f64; 4] = [0.0; 4]
    k = 0
    while k < dim {
        var s = 0.0
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * v[i] * w4[j]
                j = j + 1
            }
            i = i + 1
        }
        k4[k] = 0.0 - s
        k = k + 1
    }

    c = 0
    while c < dim {
        w[c] = w[c] + dtau / 6.0 * (k1[c] + 2.0 * k2[c] + 2.0 * k3[c] + k4[c])
        c = c + 1
    }
}

fn parallel_transport_along(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                            path: &GeodesicPath,
                            w0: &[f64; 4],
                            w_final: &![f64; 4]) with Mut, Div, Panic {
    let dim = path.dim
    let n = path.n_steps

    var c = 0
    while c < 4 { w_final[c] = 0.0; c = c + 1 }
    c = 0
    while c < dim { w_final[c] = w0[c]; c = c + 1 }

    var step = 0
    while step < n {
        var x_cur: [f64; 4] = [0.0; 4]
        var v_cur: [f64; 4] = [0.0; 4]
        c = 0
        while c < dim {
            x_cur[c] = path.x[step * dim + c]
            v_cur[c] = path.v[step * dim + c]
            c = c + 1
        }

        var dtau = 0.0
        if step + 1 < 1024 {
            dtau = path.tau[step + 1] - path.tau[step]
        }

        if dg_abs(dtau) > 1.0e-30 {
            parallel_transport_step(metric_fn, &x_cur, &v_cur, w_final, dim, dtau)
        }
        step = step + 1
    }
}

// ============================================================================
// STANDARD METRICS (copied from diffgeo.sio)
// ============================================================================

fn metric_euclidean_3d(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }
    g[0] = 1.0
    g[4] = 1.0
    g[8] = 1.0
}

fn metric_sphere_2d(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }
    let theta = x[0]
    let sth = dg_sin(theta)
    g[0] = 1.0
    g[3] = sth * sth
}

fn metric_schwarzschild(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }

    let r = x[1]
    let theta = x[2]
    let sth = dg_sin(theta)

    var r_safe = r
    if dg_abs(r_safe) < 1.0e-10 { r_safe = 1.0e-10 }
    let f = 1.0 - 2.0 / r_safe

    if dg_abs(f) < 1.0e-30 {
        g[0] = -1.0e-30
        g[5] = 1.0e30
    } else {
        g[0] = 0.0 - f
        g[5] = 1.0 / f
    }
    g[10] = r_safe * r_safe
    g[15] = r_safe * r_safe * sth * sth
}

fn metric_hyperbolic_2d(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }

    var y = x[1]
    if y < 1.0e-10 { y = 1.0e-10 }
    let inv_y2 = 1.0 / (y * y)

    g[0] = inv_y2
    g[3] = inv_y2
}

// ============================================================================
// EUCLIDEAN 2D METRIC (for geodesic/parallel transport tests)
// ============================================================================

fn metric_euclidean_2d(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }
    g[0] = 1.0
    g[3] = 1.0
}

// ============================================================================
// TEST 1: Euclidean metric is identity: diag(1,1,1)
// ============================================================================

fn test_euclidean_metric_identity() -> bool with Mut, Div, Panic {
    var x: [f64; 4] = [1.0, 2.0, 3.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_euclidean_3d(&x, 3, &!g)

    let tol = 1.0e-12

    // Check diagonal elements are 1
    if dg_abs(g[0] - 1.0) > tol { return false }
    if dg_abs(g[4] - 1.0) > tol { return false }
    if dg_abs(g[8] - 1.0) > tol { return false }

    // Check off-diagonal elements are 0
    if dg_abs(g[1]) > tol { return false }
    if dg_abs(g[2]) > tol { return false }
    if dg_abs(g[3]) > tol { return false }
    if dg_abs(g[5]) > tol { return false }
    if dg_abs(g[6]) > tol { return false }
    if dg_abs(g[7]) > tol { return false }

    true
}

// ============================================================================
// TEST 2: Metric inverse of identity: g^{-1} = g for Euclidean
// ============================================================================

fn test_euclidean_metric_inverse() -> bool with Mut, Div, Panic {
    var x: [f64; 4] = [1.0, 2.0, 3.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_euclidean_3d(&x, 3, &!g)

    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g, 3, &!g_inv)

    let tol = 1.0e-12

    // Inverse of identity is identity
    if dg_abs(g_inv[0] - 1.0) > tol { return false }
    if dg_abs(g_inv[4] - 1.0) > tol { return false }
    if dg_abs(g_inv[8] - 1.0) > tol { return false }

    if dg_abs(g_inv[1]) > tol { return false }
    if dg_abs(g_inv[2]) > tol { return false }
    if dg_abs(g_inv[3]) > tol { return false }
    if dg_abs(g_inv[5]) > tol { return false }
    if dg_abs(g_inv[6]) > tol { return false }
    if dg_abs(g_inv[7]) > tol { return false }

    true
}

// ============================================================================
// TEST 3: Flat space Christoffel symbols = 0
// ============================================================================

fn test_flat_christoffel_zero() -> bool with Mut, Div, Panic {
    var x: [f64; 4] = [1.0, 2.0, 3.0, 0.0]
    var gamma: Christoffel4 = Christoffel4 { gamma: [0.0; 64], dim: 3 }
    christoffel_from_metric(metric_euclidean_3d, &x, 3, &!gamma)

    let tol = 1.0e-4

    // All 27 Christoffel symbols should be zero for flat space
    var k = 0
    while k < 3 {
        var i = 0
        while i < 3 {
            var j = 0
            while j < 3 {
                if dg_abs(gamma.gamma[k * 9 + i * 3 + j]) > tol { return false }
                j = j + 1
            }
            i = i + 1
        }
        k = k + 1
    }

    true
}

// ============================================================================
// TEST 4: Flat space Riemann tensor = 0
// ============================================================================

fn test_flat_riemann_zero() -> bool with Mut, Div, Panic {
    var x: [f64; 4] = [1.0, 2.0, 3.0, 0.0]
    var Riem: RiemannTensor = RiemannTensor { R: [0.0; 256], dim: 3 }
    riemann_tensor(metric_euclidean_3d, &x, 3, &!Riem)

    let tol = 1.0e-4

    // All 81 components R^k_{lij} should be zero
    var k = 0
    while k < 3 {
        var l = 0
        while l < 3 {
            var i = 0
            while i < 3 {
                var j = 0
                while j < 3 {
                    if dg_abs(Riem.R[k * 27 + l * 9 + i * 3 + j]) > tol { return false }
                    j = j + 1
                }
                i = i + 1
            }
            l = l + 1
        }
        k = k + 1
    }

    true
}

// ============================================================================
// TEST 5: Sphere 2D Gaussian curvature = 1 (unit sphere)
// For a unit sphere, K = 1/R^2 = 1.
// ============================================================================

fn test_sphere_gauss_curvature() -> bool with Mut, Div, Panic {
    // Evaluate at theta = pi/3, phi = pi/4 (away from poles)
    let theta = dg_pi() / 3.0
    let phi = dg_pi() / 4.0
    var x: [f64; 4] = [theta, phi, 0.0, 0.0]

    let K = gauss_curvature_2d(metric_sphere_2d, &x)

    let tol = 1.0e-4
    dg_abs(K - 1.0) < tol
}

// ============================================================================
// TEST 6: Sphere metric at equator: g = diag(1, 1)
// At theta = pi/2, sin^2(pi/2) = 1, so g = diag(1, 1).
// ============================================================================

fn test_sphere_metric_equator() -> bool with Mut, Div, Panic {
    let theta = dg_pi() / 2.0
    var x: [f64; 4] = [theta, 0.0, 0.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_sphere_2d(&x, 2, &!g)

    let tol = 1.0e-10

    // g_{theta theta} = 1
    if dg_abs(g[0] - 1.0) > tol { return false }
    // g_{phi phi} = sin^2(pi/2) = 1
    if dg_abs(g[3] - 1.0) > tol { return false }
    // off-diagonal = 0
    if dg_abs(g[1]) > tol { return false }
    if dg_abs(g[2]) > tol { return false }

    true
}

// ============================================================================
// TEST 7: Schwarzschild metric at r=10 (M=1)
// g_tt = -(1 - 2/10) = -0.8
// g_rr = 1/(1 - 2/10) = 1/0.8 = 1.25
// ============================================================================

fn test_schwarzschild_r10() -> bool with Mut, Div, Panic {
    // x = (t, r, theta, phi) = (0, 10, pi/2, 0)
    let theta = dg_pi() / 2.0
    var x: [f64; 4] = [0.0, 10.0, theta, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_schwarzschild(&x, 4, &!g)

    let tol = 1.0e-10

    // g_tt = -(1 - 2/10) = -0.8
    let expected_gtt = 0.0 - 0.8
    if dg_abs(g[0] - expected_gtt) > tol { return false }

    // g_rr = 1/(1 - 2/10) = 1.25
    let expected_grr = 1.25
    if dg_abs(g[5] - expected_grr) > tol { return false }

    // g_{theta theta} = r^2 = 100
    if dg_abs(g[10] - 100.0) > tol { return false }

    // g_{phi phi} = r^2 sin^2(pi/2) = 100
    if dg_abs(g[15] - 100.0) > tol { return false }

    true
}

// ============================================================================
// TEST 8: Geodesic in flat space is straight line
// In Euclidean 2D, a geodesic starting at (0,0) with velocity (1,2) should
// produce a straight line x(t) = (t, 2t).
// ============================================================================

fn test_geodesic_flat_straight_line() -> bool with Mut, Div, Panic {
    let dim = 2
    var x0: [f64; 4] = [0.0, 0.0, 0.0, 0.0]
    var v0: [f64; 4] = [1.0, 2.0, 0.0, 0.0]

    let tau_end = 1.0
    let n_steps = 100

    var path: GeodesicPath = GeodesicPath {
        x: [0.0; 4096], v: [0.0; 4096], tau: [0.0; 1024],
        n_steps: 0, dim: 0
    }
    geodesic_integrate(metric_euclidean_2d, &x0, &v0, dim, tau_end, n_steps, &!path)

    let tol = 1.0e-4

    // Check final position: should be (1.0, 2.0)
    let final_x = path.x[n_steps * dim + 0]
    let final_y = path.x[n_steps * dim + 1]

    if dg_abs(final_x - 1.0) > tol { return false }
    if dg_abs(final_y - 2.0) > tol { return false }

    // Check intermediate point at step 50: should be (0.5, 1.0)
    let mid_x = path.x[50 * dim + 0]
    let mid_y = path.x[50 * dim + 1]

    if dg_abs(mid_x - 0.5) > tol { return false }
    if dg_abs(mid_y - 1.0) > tol { return false }

    true
}

// ============================================================================
// TEST 9: Parallel transport preserves norm in Euclidean space
// In flat space, parallel transport does not change the vector at all.
// The Euclidean norm ||w|| should remain constant.
// ============================================================================

fn test_parallel_transport_preserves_norm() -> bool with Mut, Div, Panic {
    let dim = 2
    var x0: [f64; 4] = [0.0, 0.0, 0.0, 0.0]
    var v0: [f64; 4] = [1.0, 0.0, 0.0, 0.0]

    let tau_end = 1.0
    let n_steps = 100

    var path: GeodesicPath = GeodesicPath {
        x: [0.0; 4096], v: [0.0; 4096], tau: [0.0; 1024],
        n_steps: 0, dim: 0
    }
    geodesic_integrate(metric_euclidean_2d, &x0, &v0, dim, tau_end, n_steps, &!path)

    // Transport w0 = (3, 4) along this geodesic
    var w0: [f64; 4] = [3.0, 4.0, 0.0, 0.0]
    var w_final: [f64; 4] = [0.0; 4]
    parallel_transport_along(metric_euclidean_2d, &path, &w0, &!w_final)

    // Initial norm: sqrt(9 + 16) = 5
    let norm0 = dg_sqrt(w0[0] * w0[0] + w0[1] * w0[1])
    let norm_final = dg_sqrt(w_final[0] * w_final[0] + w_final[1] * w_final[1])

    let tol = 1.0e-4
    dg_abs(norm_final - norm0) < tol
}

// ============================================================================
// TEST 10: Hyperbolic plane curvature = -1
// Poincare half-plane ds^2 = (dx^2 + dy^2)/y^2 has K = -1.
// ============================================================================

fn test_hyperbolic_curvature() -> bool with Mut, Div, Panic {
    // Evaluate at (x, y) = (1.0, 2.0) -- well inside the half-plane
    var x: [f64; 4] = [1.0, 2.0, 0.0, 0.0]

    let K = gauss_curvature_2d(metric_hyperbolic_2d, &x)

    let tol = 1.0e-4
    let expected = 0.0 - 1.0
    dg_abs(K - expected) < tol
}

// ============================================================================
// TEST 11: Metric determinant of sphere
// det(g) = 1 * sin^2(theta) - 0 = sin^2(theta)
// At theta = pi/4: sin^2(pi/4) = 0.5
// ============================================================================

fn test_sphere_metric_determinant() -> bool with Mut, Div, Panic {
    let theta = dg_pi() / 4.0
    var x: [f64; 4] = [theta, 0.0, 0.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_sphere_2d(&x, 2, &!g)

    let det = metric_det(&g, 2)

    // sin^2(pi/4) = (sqrt(2)/2)^2 = 0.5
    let expected = 0.5
    let tol = 1.0e-10

    dg_abs(det - expected) < tol
}

// ============================================================================
// TEST 12: Raise and lower index roundtrip
// Lower then raise a vector: v -> v_lower -> v_upper should give back v.
// Using Euclidean 3D metric (identity), this is trivial.
// Also test with sphere metric at theta = pi/3 for non-trivial case.
// ============================================================================

fn test_raise_lower_roundtrip() -> bool with Mut, Div, Panic {
    // Non-trivial test: sphere metric at theta = pi/3
    let theta = dg_pi() / 3.0
    var x: [f64; 4] = [theta, 0.0, 0.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_sphere_2d(&x, 2, &!g)

    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g, 2, &!g_inv)

    // Original vector v^i = (1.0, 2.0)
    var v_upper: [f64; 4] = [1.0, 2.0, 0.0, 0.0]

    // Lower: v_i = g_{ij} v^j
    var v_lower: [f64; 4] = [0.0; 4]
    metric_lower_index(&g, &v_upper, 2, &!v_lower)

    // Raise back: v'^i = g^{ij} v_j
    var v_raised: [f64; 4] = [0.0; 4]
    metric_raise_index(&g_inv, &v_lower, 2, &!v_raised)

    let tol = 1.0e-10

    // v_raised should equal v_upper
    if dg_abs(v_raised[0] - v_upper[0]) > tol { return false }
    if dg_abs(v_raised[1] - v_upper[1]) > tol { return false }

    true
}

